package com.cpf.starter.notification;import java.sql.Timestamp;import java.time.Instant;import java.util.*;import org.springframework.dao.DuplicateKeyException;import org.springframework.jdbc.core.JdbcTemplate;
public final class JdbcCpfNotificationOutbox {private final JdbcTemplate jdbc;public JdbcCpfNotificationOutbox(JdbcTemplate j){jdbc=j;}public CpfNotificationResult enqueue(CpfNotificationRequest r){try{jdbc.update("INSERT INTO cpf_notification_outbox(notification_id,channel_code,recipient_value,template_id,variable_json,idempotency_key,transaction_id,notification_status,attempt_count,max_attempts,next_attempt_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'PENDING',0,5,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",r.notificationId(),r.channel(),r.recipient(),r.templateId(),encode(r.variables()),r.idempotencyKey(),r.transactionId(),r.notBefore()==null?null:Timestamp.from(r.notBefore()));return new CpfNotificationResult(r.notificationId(),"OUTBOX","ACCEPTED",null,null,Instant.now());}catch(DuplicateKeyException ex){var rows=jdbc.queryForList("SELECT notification_id AS notificationId,notification_status AS status,provider_name AS providerName,provider_message_id AS providerMessageId,result_detail AS detail,updated_at AS updatedAt FROM cpf_notification_outbox WHERE idempotency_key=?",r.idempotencyKey());if(rows.isEmpty())throw ex;var x=rows.getFirst();return new CpfNotificationResult(String.valueOf(x.get("notificationId")),String.valueOf(x.get("providerName")),String.valueOf(x.get("status")),x.get("providerMessageId")==null?null:String.valueOf(x.get("providerMessageId")),x.get("detail")==null?null:String.valueOf(x.get("detail")),Instant.now());}}
 public List<CpfNotificationRequest> claim(String worker,int limit){List<Map<String,Object>> rows=jdbc.queryForList("SELECT notification_id,channel_code,recipient_value,template_id,variable_json,idempotency_key,transaction_id,next_attempt_at FROM cpf_notification_outbox WHERE notification_status='PENDING' AND (next_attempt_at IS NULL OR next_attempt_at<=CURRENT_TIMESTAMP) ORDER BY created_at");List<CpfNotificationRequest> result=new ArrayList<>();for(var x:rows.stream().limit(Math.max(1,Math.min(limit,500))).toList()){String id=String.valueOf(x.get("notification_id"));int n=jdbc.update("UPDATE cpf_notification_outbox SET notification_status='CLAIMED',worker_id=?,lease_until=?,updated_at=CURRENT_TIMESTAMP WHERE notification_id=? AND notification_status='PENDING'",worker,Timestamp.from(Instant.now().plusSeconds(30)),id);if(n==1)result.add(new CpfNotificationRequest(id,String.valueOf(x.get("channel_code")),String.valueOf(x.get("recipient_value")),String.valueOf(x.get("template_id")),decode(String.valueOf(x.get("variable_json"))),String.valueOf(x.get("idempotency_key")),String.valueOf(x.get("transaction_id")),null));}return List.copyOf(result);}
 public void complete(CpfNotificationResult r){int n=jdbc.update("UPDATE cpf_notification_outbox SET notification_status=?,provider_name=?,provider_message_id=?,result_detail=?,attempt_count=attempt_count+1,worker_id=NULL,lease_until=NULL,completed_at=?,updated_at=CURRENT_TIMESTAMP WHERE notification_id=? AND notification_status='CLAIMED'",r.status(),r.provider(),r.providerMessageId(),r.detail(),Timestamp.from(r.processedAt()),r.notificationId());if(n!=1)throw new IllegalStateException("notification outbox state conflict: "+r.notificationId());}
 public void retry(String id,String detail,Instant next){int n=jdbc.update("UPDATE cpf_notification_outbox SET notification_status=CASE WHEN attempt_count+1>=max_attempts THEN 'DLQ' ELSE 'PENDING' END,attempt_count=attempt_count+1,result_detail=?,next_attempt_at=?,worker_id=NULL,lease_until=NULL,updated_at=CURRENT_TIMESTAMP WHERE notification_id=? AND notification_status='CLAIMED'",detail,Timestamp.from(next),id);if(n!=1)throw new IllegalStateException("notification retry conflict: "+id);}
 private static String encode(Map<String,String> m){StringJoiner j=new StringJoiner("&");m.forEach((k,v)->j.add(Base64.getUrlEncoder().withoutPadding().encodeToString(k.getBytes(java.nio.charset.StandardCharsets.UTF_8))+"="+Base64.getUrlEncoder().withoutPadding().encodeToString(v.getBytes(java.nio.charset.StandardCharsets.UTF_8))));return j.toString();}private static Map<String,String> decode(String s){if(s==null||s.isBlank()||"null".equals(s))return Map.of();Map<String,String> m=new LinkedHashMap<>();for(String e:s.split("&")){String[] p=e.split("=",2);if(p.length==2)m.put(new String(Base64.getUrlDecoder().decode(p[0]),java.nio.charset.StandardCharsets.UTF_8),new String(Base64.getUrlDecoder().decode(p[1]),java.nio.charset.StandardCharsets.UTF_8));}return Map.copyOf(m);}}
